import { Download } from 'lucide-react';

import { useLanguage } from '../i18n/LanguageProvider';
import type { LocaleCode } from '../i18n';

/** The CV is generated by `pnpm cv` into `public/cv/`, one PDF per locale. */
export const cvHref = (code: LocaleCode): string => `/cv/miguel-orjuela-${code}.pdf`;

type Props = {
  readonly variant?: 'solid' | 'ghost';
  readonly compact?: boolean;
};

export const CvDownloadLink = ({ variant = 'solid', compact = false }: Props) => {
  const { locale } = useLanguage();

  const base =
    'inline-flex items-center gap-2 rounded-[var(--radius-tight)] font-mono text-[11px] font-semibold uppercase tracking-wider transition-colors';
  const palette =
    variant === 'solid'
      ? 'bg-ink text-white hover:bg-clay'
      : 'border border-line bg-raised text-ink hover:border-clay hover:text-clay';
  const sizing = compact ? 'px-3 py-1.5' : 'px-4 py-2.5';

  return (
    <a href={cvHref(locale.code)} download className={`${base} ${palette} ${sizing}`}>
      <Download size={13} aria-hidden />
      {locale.ui.cv.download}
    </a>
  );
};
